//! Values recorded while an assertion evaluates, and the panic on failure.

use crate::render::render;

/// The assertion's source line and the position of each recorded value in
/// it, generated by the macro.
pub struct Layout<'a> {
    /// The assertion expression on one line, as the macro prints it.
    pub source: &'a str,
    /// One entry per recorded subexpression, indexed by slot.
    pub slots: &'a [Slot],
}

/// Position of a recorded subexpression in [`Layout::source`].
pub struct Slot {
    /// Character offset of the token the value is shown under.
    pub column: usize,
    /// Byte offset where the subexpression's text starts.
    pub start: usize,
    /// Byte offset where the subexpression's text ends.
    pub end: usize,
}

/// Values recorded by one assertion, one per slot.
///
/// `None` means the subexpression did not run, or its type has no `Debug`.
pub struct Recorder {
    values: Vec<Option<String>>,
}

impl Recorder {
    /// Creates a recorder with `slots` empty slots.
    #[must_use]
    pub fn new(slots: usize) -> Self {
        Self {
            values: vec![None; slots],
        }
    }

    /// Stores the rendering of the value in `slot`.
    #[inline]
    pub fn record(&mut self, slot: usize, value: Option<String>) {
        self.values[slot] = value;
    }

    /// The recorded values, indexed by slot.
    #[must_use]
    pub fn values(&self) -> &[Option<String>] {
        &self.values
    }
}

/// Reports a failed assertion.
///
/// # Panics
///
/// Always, with the rendered diagram as the message and the assertion's call
/// site as the location.
#[cold]
#[inline(never)]
#[track_caller]
pub fn fail(layout: &Layout<'_>, recorder: &Recorder, message: Option<String>) -> ! {
    let diagram = render(layout, recorder.values());
    match message {
        Some(message) => panic!("assertion failed: {message}\n\n{diagram}"),
        None => panic!("assertion failed\n\n{diagram}"),
    }
}
